def steps_to_anagram(s, t):
    count = [0] * 26
    for ch in s:
        count[ord(ch) - ord("a")] += 1
    for ch in t:
        count[ord(ch) - ord("a")] -= 1
    return sum(c for c in count if c > 0)

code.java:
static int stepsToAnagram(String s, String t) {
    int[] count = new int[26];
    for (char ch : s.toCharArray()) count[ch - 'a']++;
    for (char ch : t.toCharArray()) count[ch - 'a']--;
    int steps = 0;
    for (int c : count) if (c > 0) steps += c;
    return steps;
}

code.cpp:
int stepsToAnagram(const string& s, const string& t) {
    int count[26] = {0};
    for (char ch : s) count[ch - 'a']++;
    for (char ch : t) count[ch - 'a']--;
    int steps = 0;
    for (int c : count) if (c > 0) steps += c;
    return steps;
}

code.c:
int stepsToAnagram(const char* s, const char* t) {
    int count[26] = {0};
    for (const char* p = s; *p; p++) count[*p - 'a']++;
    for (const char* p = t; *p; p++) count[*p - 'a']--;
    int steps = 0;
    for (int i = 0; i < 26; i++) if (count[i] > 0) steps += count[i];
    return steps;
}

