def can_be_palindrome(s):
    odd = 0
    for ch in s:
        odd ^= 1 << (ord(ch) - ord("a"))
    return odd & (odd - 1) == 0

code.java:
static boolean canBePalindrome(String s) {
    int odd = 0;
    for (char ch : s.toCharArray()) odd ^= 1 << (ch - 'a');
    return (odd & (odd - 1)) == 0;
}

code.cpp:
bool canBePalindrome(const string& s) {
    unsigned odd = 0;
    for (char ch : s) odd ^= 1u << (ch - 'a');
    return (odd & (odd - 1)) == 0;
}

